mapper.delete:
DELETE FROM CHIPSET_CELL
WHERE ROW_SEQ IN (
  SELECT ROW_SEQ FROM CHIPSET_ROW
  WHERE UPLOAD_SEQ IN (
    SELECT UPLOAD_SEQ FROM CHIPSET_UPLOAD WHERE FILE_TYPE = #{fileType}
  )
)

DELETE FROM CHIPSET_ROW
WHERE UPLOAD_SEQ IN (
  SELECT UPLOAD_SEQ FROM CHIPSET_UPLOAD WHERE FILE_TYPE = #{fileType}
)

DELETE FROM CHIPSET_CHIP_COL
WHERE UPLOAD_SEQ IN (
  SELECT UPLOAD_SEQ FROM CHIPSET_UPLOAD WHERE FILE_TYPE = #{fileType}
)

DELETE FROM RAWDATA_ROW
WHERE UPLOAD_SEQ IN (
  SELECT UPLOAD_SEQ FROM CHIPSET_UPLOAD WHERE FILE_TYPE = #{fileType}
)

mapper.select:
SELECT CELL_SEQ, ROW_SEQ, COL_SEQ, CELL_VALUE, BG_COLOR
FROM CHIPSET_CELL
WHERE ROW_SEQ = #{rowSeq}

SELECT CELL_SEQ, ROW_SEQ, COL_SEQ, CELL_VALUE, BG_COLOR
FROM CHIPSET_CELL_H
WHERE ROW_SEQ    = #{rowSeq}
  AND UPLOAD_SEQ = #{uploadSeq}
